class RevbXtaInstruction_ZEXT_rus extends XtaInstruction {
    RevbXtaInstruction_ZEXT_rus(int opcode, int pc) {
        super("ZEXT_rus", opcode, pc, 2, false, false);
    }

    public void execute(MachineState state) {
        state.m_op1Fld = decode2OpSrcDst(state.m_opcode);
        state.m_op2 = new Expression(decode2OpSrc(state.m_opcode));
        state.m_op1 = new Expression(state.readRegister(state.m_op1Fld));
        int ranges[][] = {{BITS_PER_WORD, BITS_PER_WORD}, {1, 8}, {16, 16}, {24, 24}, {32, 32}};
        int mapsTo[][] = {{0, 0}, {1, 8}, {9, 9}, {10, 10}, {11, 11}};
        state.m_op2 = reverseMap(state.m_op2, 5, ranges, mapsTo);
        ZEXT(state);
        state.writeRegister(state.m_op1Fld, state.m_op1);
    }

    public String getOperandString() {
        int opcode = getOpcode();
        int ranges[][] = {{BITS_PER_WORD, BITS_PER_WORD}, {1, 8}, {16, 16}, {24, 24}, {32, 32}};
        int mapsTo[][] = {{0, 0}, {1, 8}, {9, 9}, {10, 10}, {11, 11}};
        return String.format("r%d, i 0x%x",
            decode2OpSrcDst(opcode),
            reverseMap(decode2OpSrc(opcode), 5, ranges, mapsTo));
    }
}

